const suggestions=["Rice","Onion","Tomato","Egg","Potato","Paneer","Chicken","Garlic","Ginger","Green Chilli","Pasta","Cheese"];
function App(){
const[recipes,setRecipes]=useState(fallback),[ingredients,setIngredients]=useState([]),[input,setInput]=useState(""),[selected,setSelected]=useState(null),[tab,setTab]=useState("discover"),[cuisine,setCuisine]=useState("All"),[favorites,setFavorites]=useState(()=>JSON.parse(localStorage.getItem("nb-favs")||"[]")),[cooking,setCooking]=useState(false),[step,setStep]=useState(0),[seconds,setSeconds]=useState(0),[timer,setTimer]=useState(false);
useEffect(()=>{fetch(API+"/recipes").then(r=>r.json()).then(d=>d.length&&setRecipes(d)).catch(()=>{})},[]);
useEffect(()=>localStorage.setItem("nb-favs",JSON.stringify(favorites)),[favorites]);
useEffect(()=>{if(!timer||seconds<=0)return;const t=setInterval(()=>setSeconds(s=>s-1),1000);return()=>clearInterval(t)},[timer,seconds]);
useEffect(()=>{if(seconds===0&&timer)setTimer(false)},[seconds,timer]);
const add=()=>{let v=input.trim();if(v&&!ingredients.includes(v))setIngredients([...ingredients,v]);setInput("")};
const matches=r=>{if(!ingredients.length)return 70;const names=r.ingredients.map(x=>x.name.toLowerCase()),have=ingredients.map(x=>x.toLowerCase()),hits=names.filter(n=>have.some(h=>n.includes(h)||h.includes(n))).length;return Math.min(99,Math.round(35+65*hits/Math.max(1,names.length)))};
const filtered=useMemo(()=>recipes.filter(r=>cuisine==="All"||r.cuisine===cuisine).sort((a,b)=>matches(b)-matches(a)),[recipes,cuisine,ingredients]);
const open=r=>{setSelected(r);setStep(0);setCooking(false);setTimer(false);setSeconds(0)};
const fav=id=>setFavorites(favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id]);
const fmt=s=>`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;
if(selected)return <Recipe recipe={selected} score={matches(selected)} fav={favorites.includes(selected.id)} onFav={()=>fav(selected.id)} onBack={()=>setSelected(null)} cooking={cooking} setCooking={setCooking} step={step} setStep={setStep} seconds={seconds} setSeconds={setSeconds} timer={timer} setTimer={setTimer} fmt={fmt}/>;
return <div className="app"><header className="nav"><div className="brand" onClick={()=>setTab("discover")}><span className="brand-mark">N</span><span>Nal<span>Bheema</span></span></div><nav><button className={tab==="discover"?"active":""} onClick={()=>setTab("discover")}>Discover</button><button className={tab==="kitchen"?"active":""} onClick={()=>setTab("kitchen")}>My Kitchen</button></nav><div className="nav-badge"><ChefHat size={16}/> Cook smarter</div></header>
<main><section className="hero"><div className="hero-copy"><div className="eyebrow"><Sparkles size={15}/> Your kitchen. Your ingredients. Your next masterpiece.</div><h1>Turn what you have<br/><em>into something amazing.</em></h1><p>NalBheema finds recipes around the ingredients already sitting in your kitchen — then guides you through every step.</p><div className="ingredient-box"><div className="input-row"><Search size={20}/><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&add()} placeholder="Add an ingredient… e.g. tomato"/><button onClick={add}><Plus size={19}/> Add</button></div>{ingredients.length>0&&<div className="chips">{ingredients.map(x=><span key={x}>{x}<X size={13} onClick={()=>setIngredients(ingredients.filter(i=>i!==x))}/></span>)}</div>}<div className="quick"><small>Quick add</small>{suggestions.map(x=><button key={x} onClick={()=>!ingredients.includes(x)&&setIngredients([...ingredients,x])}>{x}</button>)}</div></div></div><div className="hero-visual"><div className="orb"></div><div className="plate"><div className="dish">🍛</div></div><div className="float-card fc1"><Flame size={16}/> 98% ingredient match</div><div className="float-card fc2"><Timer size={16}/> 24 min cook time</div></div></section>
<section className="content"><div className="section-head"><div><p className="eyebrow">EXPLORE THE COLLECTION</p><h2>{ingredients.length?"Recipes made for your kitchen":"What are you craving?"}</h2></div><button className="surprise" onClick={()=>open(filtered[Math.floor(Math.random()*filtered.length)])}><Sparkles size={17}/> Surprise me</button></div><div className="filters">{["All","Indian","Italian","Japanese","American"].map(c=><button key={c} className={cuisine===c?"selected":""} onClick={()=>setCuisine(c)}>{c}</button>)}</div>{tab==="kitchen"?<div className="empty"><ShoppingBasket size={48}/><h3>Your kitchen is ready.</h3><p>Add ingredients above and NalBheema will build your recipe shortlist.</p></div>:<div className="grid">{filtered.slice(0,12).map((r,i)=><Card key={r.id} r={r} score={matches(r)} i={i} fav={favorites.includes(r.id)} onFav={()=>fav(r.id)} onOpen={()=>open(r)}/>)}</div>}</section></main><footer><div className="brand"><span className="brand-mark">N</span><span>Nal<span>Bheema</span></span></div><p>Cook boldly. Waste less. Eat wonderfully.</p><small>120 recipes • Interactive cooking • Smart ingredient matching</small></footer></div>}
function Card({r,score,i,fav,onFav,onOpen}){return <article className="card" style={{"--delay":`${i*45}ms`}} onClick={onOpen}><div className="card-img" style={{backgroundImage:`url(${r.image})`}}><div className="match"><Sparkles size={12}/> {score}% match</div><button className={"heart "+(fav?"liked":"")} onClick={e=>{e.stopPropagation();onFav()}}><Heart size={17} fill={fav?"currentColor":"none"}/></button></div><div className="card-body"><div className="mini">{r.cuisine} · {r.difficulty}</div><h3>{r.name}</h3><p>{r.description}</p><div className="meta"><span><Clock3 size={15}/> {r.prepMinutes+r.cookMinutes} min</span><span><Users size={15}/> {r.servings}</span><span><Flame size={15}/> {r.category}</span></div></div></article>}
function Recipe({recipe,score,fav,onFav,onBack,cooking,setCooking,step,setStep,seconds,setSeconds,timer,setTimer,fmt}){const s=recipe.steps[step];const start=()=>{setSeconds(s.duration*60);setTimer(true)};return <div className="recipe-page"><header className="nav"><button className="back" onClick={onBack}>← Back to recipes</button><div className="brand"><span className="brand-mark">N</span><span>Nal<span>Bheema</span></span></div><button className={"heart topheart "+(fav?"liked":"")} onClick={onFav}><Heart size={18} fill={fav?"currentColor":"none"}/></button></header><main className="recipe-main"><div className="recipe-hero" style={{backgroundImage:`linear-gradient(90deg,rgba(8,10,12,.92),rgba(8,10,12,.3)),url(${recipe.image})`}}><div className="recipe-title"><div className="mini">{recipe.cuisine} · {recipe.difficulty}</div><h1>{recipe.name}</h1><p>{recipe.description}</p><div className="recipe-stats"><span><Clock3/> {recipe.prepMinutes+recipe.cookMinutes} min</span><span><Users/> {recipe.servings} servings</span><span><Sparkles/> {score}% match</span></div><button className="primary" onClick={()=>setCooking(true)}><ChefHat/> Cook with me <ArrowRight/></button></div></div>{!cooking?<div className="recipe-grid"><aside><div className="panel"><h3>Ingredients</h3>{recipe.ingredients.map(x=><label key={x.name}><span className="check"></span><span>{x.name}</span><b>{x.amount}</b></label>)}</div><div className="panel missing"><h3>Kitchen tip</h3><p>Prep everything before heating the pan. A calm kitchen makes better food.</p></div></aside><section><div className="steps-head"><div><p className="eyebrow">THE COOKING FLOW</p><h2>Follow the rhythm</h2></div><span>{recipe.steps.length} steps</span></div>{recipe.steps.map((x,i)=><div className="step-card" key={x.title}><div className="step-num">0{i+1}</div><div className={"step-anim "+x.animation}><div className="pan"></div><div className="food"></div></div><div><h3>{x.title}</h3><p>{x.instruction}</p><span className="duration"><Timer size={14}/> {x.duration} min</span></div></div>)}</section></div>:<section className="cook-mode"><div className="progress"><span style={{width:`${((step+1)/recipe.steps.length)*100}%`}}></span></div><div className="cook-top"><span>COOK WITH ME</span><b>STEP {step+1} / {recipe.steps.length}</b></div><div className={"big-animation "+s.animation}><div className="big-pan"></div><div className="big-food">🍳</div></div><p className="eyebrow">NOW DO THIS</p><h2>{s.title}</h2><p className="instruction">{s.instruction}</p><div className="timer-box"><Timer size={22}/><strong>{fmt(seconds)}</strong>{timer?<button onClick={()=>setTimer(false)}>PAUSE</button>:<button onClick={start}>{seconds?"RESUME":"START TIMER"}</button>}</div><div className="cook-actions"><button disabled={step===0} onClick={()=>setStep(step-1)}>← Previous</button><button className="primary" onClick={()=>step===recipe.steps.length-1?setCooking(false):setStep(step+1)}>{step===recipe.steps.length-1?"Finish":"Next step"} <ArrowRight/></button></div></section>}</main></div>}
createRoot(document.getElementById("root")).render(<App/>);
